        mime_data = QMimeData()
        mime_data.setUrls([QUrl.fromLocalFile("/test/document.pdf")])

        event = MagicMock(spec=QDropEvent)
        event.mimeData.return_value = mime_data

        # Simulate drop on drop zone
        document_panel.drop_zone.dropEvent(event)

        # Model should now have the document
        assert document_panel.model.document_count == 1

    def test_files_received_signal_emitted(
        self, document_panel: DocumentPanel, qtbot
    ) -> None:
        """Test files_received signal is emitted when files added."""
        with qtbot.waitSignal(document_panel.files_received) as blocker:
            # Create mock drop event
            mime_data = QMimeData()
            mime_data.setUrls([QUrl.fromLocalFile("/test/document.pdf")])

            event = MagicMock(spec=QDropEvent)
            event.mimeData.return_value = mime_data

            document_panel.drop_zone.dropEvent(event)

        assert len(blocker.args[0]) == 1

    def test_invalid_files_rejected_signal_forwarded(
        self, document_panel: DocumentPanel, qtbot
    ) -> None:
        """Test invalid_files_rejected signal is forwarded from drop zone."""
        with qtbot.waitSignal(
            document_panel.invalid_files_rejected
        ) as blocker:
            # Create mock drop event with non-PDF file
            mime_data = QMimeData()
            mime_data.setUrls([QUrl.fromLocalFile("/test/image.jpg")])

            event = MagicMock(spec=QDropEvent)
            event.mimeData.return_value = mime_data

            document_panel.drop_zone.dropEvent(event)

        assert blocker.args[0] == 1


